<script setup lang="ts">
import {ref,watch,nextTick} from 'vue'
import {useCatalogText} from '../text'
import {displayName} from '../../shared-commerce/format'
import type {Category} from '../types'
import CatalogBarcodeFields from './CatalogBarcodeFields.vue'
import {useCatalogProductEditor,type ProductDetail} from './useCatalogProductEditor'
const props=defineProps<{base:string;productId:string|null;categories:Category[];globalEdit:boolean;defaultChannels?:readonly string[]}>(),emit=defineEmits<{saved:[ProductDetail];cancel:[];busy:[boolean]}>(),{t,locale}=useCatalogText(),discard=ref(false),discardPanel=ref<HTMLElement|null>(null),discardAction=ref<'back'|'reload'>('back')
const{form,rows,product,loaded,loading,saving,error,notice,pending,blocked,dirty,save,load,recover}=useCatalogProductEditor(props,t,value=>emit('saved',value))
watch(blocked,v=>emit('busy',v),{immediate:true})
watch(discard,async value=>{if(value){await nextTick();discardPanel.value?.querySelector?.('button')?.focus()}})
function trapTab(event:KeyboardEvent){const buttons=discardPanel.value?.querySelectorAll<HTMLButtonElement>('button');if(!buttons?.length)return;event.preventDefault();const index=Array.from(buttons).indexOf(document.activeElement as HTMLButtonElement);buttons[(index+(event.shiftKey?-1:1)+buttons.length)%buttons.length].focus()}
function refresh(){if(blocked.value)return;discardAction.value='reload';if(dirty.value)discard.value=true;else void load()}
function confirmDiscard(){discard.value=false;if(discardAction.value==='reload')void load();else emit('cancel')}
function back(){if(blocked.value)return;discardAction.value='back';if(dirty.value)discard.value=true;else emit('cancel')}
</script>
<template><section class="cards-panel catalog-product-editor"><header class="cards-actions"><h2>{{t(productId?'editProduct':'newProduct')}}</h2><button type="button" :disabled="blocked" @click="back">← {{t('backToList')}}</button></header><p v-if="error&&!loaded" class="cards-error" role="alert">{{error}}</p><p v-if="loading||saving" role="status">{{t('loading')}}</p><button v-if="!loaded&&!loading" type="button" @click="load">{{t('retryLoad')}}</button><form v-if="loaded" @submit.prevent="save"><fieldset :disabled="blocked" style="border:0;padding:0;margin:0"><fieldset :disabled="!globalEdit" style="border:0;padding:0;margin:0"><div class="cards-grid"><label>{{t('code')}}<input v-model="form.code" required maxlength="80" :disabled="!!product"></label><label>{{t('category')}}<select v-model="form.categoryId" required><option value="">{{t('select')}}</option><option v-for="c in categories" :key="c.id" :value="c.id">{{displayName(c,locale)}}</option></select></label><label>{{t('nameZh')}}<input v-model="form.nameZh"></label><label>{{t('nameEn')}}<input v-model="form.nameEn"></label><label>{{t('descriptionZh')}}<textarea v-model="form.descriptionZh" /></label><label>{{t('descriptionEn')}}<textarea v-model="form.descriptionEn" /></label><label>{{t('kind')}}<select v-model="form.kind"><option value="physical">{{t('physical')}}</option><option value="service">{{t('service')}}</option></select></label><label>{{t('unit')}}<input v-model="form.unit" required></label><label>{{t('image')}}<input v-model="form.imageUrl"></label></div></fieldset><div class="cards-grid"><label>{{t('price')}}<input v-model="form.price" inputmode="decimal" :required="!form.channels.every(c=>c==='storage')"></label><label>{{t('inclusive')}} / {{t('exclusive')}}<select v-model="form.taxMode" :disabled="!globalEdit"><option value="inclusive">{{t('inclusive')}}</option><option value="exclusive">{{t('exclusive')}}</option></select></label><label>{{t('taxCategory')}}<select v-model="form.taxCategory" :disabled="!globalEdit" @change="form.taxCategory!=='taxable'&&(form.taxRate='0')"><option v-for="v in ['taxable','zero','exempt','not_applicable']" :key="v" :value="v">{{t(v)}}</option></select></label><label>{{t('taxRate')}}<input v-model="form.taxRate" :disabled="!globalEdit||form.taxCategory!=='taxable'" inputmode="decimal"></label></div><p class="cards-muted">{{t('taxHint')}}</p><div class="cards-actions"><span>{{t('channels')}}</span><label v-for="v in ['cards','rewards','shopping','storage']" :key="v" class="check"><input v-model="form.channels" type="checkbox" :value="v">{{t(v)}}</label></div><CatalogBarcodeFields v-if="form.kind==='physical'||rows.length" v-model="rows" :disabled="blocked" :read-only="!globalEdit"/><p v-if="error" class="cards-error" role="alert">{{error}}</p><button v-if="error&&!blocked" type="button" @click="refresh">{{t('retryLoad')}}</button><p v-if="notice" class="cards-notice" role="status">{{t('savedAll')}}</p><p v-if="saving" role="status">{{t('loading')}}</p><div class="cards-actions"><button class="primary" type="submit" :disabled="blocked">{{t(globalEdit?'saveAll':'save')}}</button><button type="button" :disabled="blocked" @click="back">{{t('cancelEdit')}}</button></div></fieldset></form><div v-if="pending&&!saving" class="cards-notice"><p>{{t('pendingEdit')}}</p><button type="button" :disabled="loading" @click="recover">{{t('recover')}}</button></div><div v-if="discard" class="catalog-discard-overlay"><section ref="discardPanel" role="dialog" aria-modal="true" :aria-label="t(discardAction==='reload'?'unsavedReload':'unsaved')" class="cards-notice catalog-discard-dialog" @keydown.esc.prevent="discard=false" @keydown.tab="trapTab"><p>{{t(discardAction==='reload'?'unsavedReload':'unsaved')}}</p><button type="button" @click="confirmDiscard">{{t('discard')}}</button><button type="button" @click="discard=false">{{t('keepEditing')}}</button></section></div></section></template>

<style scoped>.catalog-discard-overlay{position:fixed;inset:0;z-index:200;background:#10263380;display:grid;place-items:center;padding:16px}.catalog-discard-dialog{width:100%;max-width:520px;box-sizing:border-box;padding:22px;background:white;border:1px solid #cbdde0;border-radius:14px}.catalog-discard-dialog button{margin:6px}</style>
